// === Tab: mySketch ===
let particles   = [];
let targets     = [];
let trailLayer;
let customFont;

let revealIndex = 0;
const REVEAL_SPEED  = 40;
const MAX_PARTICLES = 8800;
const GRID_STEP     = 5;
const CELL          = 12;

let spatialGrid = {};
let lastReveal  = -1;

// A few defined hues (0–360) for the flowing particles, instead of the full rainbow.
// Edit this list to taste — add/remove entries, or swap the values for a different mood.
//const PALETTE_HUES = [205, 275, 330, 15]; // blue, violet, pink, coral
const PALETTE_HUES = [150, 330, 200, 300];


function preload() {
  customFont = loadFont(
    'https://fonts.gstatic.com/s/mplusu/v1/-W_gXJfyAgH86Tq6MsATZrf75i4iYyIxg0A-qg.ttf'
  );
}

// ── setup ────────────────────────────────────────────────────
function setup() {
  createCanvas(1920, 1098);
  colorMode(RGB, 255);

  // Trail layer runs in HSB so hue can flow smoothly for the
  // colorful particles, while still fading toward WHITE explicitly
  // (a bare fill(0, alpha) would fade toward black under HSB, since
  // a lone value is read as brightness — so fades below spell out h,s,b,a).
  trailLayer = createGraphics(width, height);
  trailLayer.colorMode(HSB, 360, 100, 100, 255);
  trailLayer.background(0, 0, 100); // white

  // Off-screen buffer purely for pixel-sampling the text shape
  // (kept black bg / white text — never displayed, just sampled)
  let pg = createGraphics(width, height);
  pg.pixelDensity(1);
  pg.background(0);
  pg.fill(255);
  pg.noStroke();
  pg.textFont(customFont);
  pg.textSize(320);
  pg.textAlign(CENTER, CENTER);
  pg.text('MEET UP?', pg.width / 2, pg.height / 2);
  pg.loadPixels();

  for (let x = 0; x < pg.width; x += GRID_STEP) {
    for (let y = 0; y < pg.height; y += GRID_STEP) {
      let idx = (x + y * pg.width) * 4;
      if (pg.pixels[idx] > 200) {
        targets.push({ x: x, y: y, claimed: false });
      }
    }
  }
  targets.sort((a, b) => a.x - b.x);
  pg.remove();

	//frameRate(1);   //*** For slowing down
}

// ── draw ─────────────────────────────────────────────────────
function draw() {
  revealIndex = min(revealIndex + REVEAL_SPEED, targets.length);

  if (revealIndex !== lastReveal) {
    spatialGrid = {};
    for (let i = 0; i < revealIndex; i++) {
      let t = targets[i];
      if (t.claimed) continue;
      let key = floor(t.x / CELL) + ',' + floor(t.y / CELL);
      if (!spatialGrid[key]) spatialGrid[key] = [];
      spatialGrid[key].push(t);
    }
    lastReveal = revealIndex;
  }

  if (particles.length < MAX_PARTICLES) {
    let spawn = min(24, MAX_PARTICLES - particles.length);
    for (let i = 0; i < spawn; i++) particles.push(new Particle());
  }

  // Fade the trail toward WHITE instead of black
  trailLayer.noStroke();
  trailLayer.fill(0, 0, 100, 38);
  trailLayer.rect(0, 0, width, height);

  let sway = sin(frameCount * 0.003) * 1.4;
  trailLayer.push();
  trailLayer.translate(sway, 0);

  let living = [];
  let stuck  = [];
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.update();
    if (p.stuck) {
      stuck.push(p);
    } else if (p.x > width + 20 || p.x < -20 || p.y < -20 || p.y > height + 20) {
      particles.splice(i, 1);
    } else {
      living.push(p);
    }
  }

  // Living particles — colorful, flowing hue (shifts with time + position)
  // Drawn first so the settled text (below) always renders on top of them.
  for (let p of living) {
    let hue = (p.hueBase + sin(frameCount * 0.02 + p.x * 0.01) * 20 + 360) % 360;

    if (p.shapeType === 1) {
      trailLayer.stroke(hue, 45, 100, 150);
      trailLayer.strokeWeight(p.size * 0.5);
      trailLayer.line(p.x - p.vx * 2, p.y - p.vy * 2, p.x, p.y);
      trailLayer.noStroke();
    } else {
      trailLayer.noStroke();
      trailLayer.fill(hue, 45, 60, 190);
      trailLayer.ellipse(p.x, p.y, p.size);
    }
  }

  // Stuck particles — muted, dark settled color (frozen hue, moderate sat, low brightness).
  // Drawn last + oversized so adjacent dots overlap into a solid, unmistakable letterform.
  trailLayer.noStroke();
  for (let p of stuck) {
    var t = p.age / 255.0;
    let sat = 42 + t * 14;   // rich but not neon
    let bri = 50 + t * 14;   // stays dark, reads as "ink"
    trailLayer.fill(p.stuckHue, sat, bri, 80 + t * 10);
    trailLayer.ellipse(p.x, p.y, p.size * 1.9);
  }

  trailLayer.pop();

  background(255);
  imageMode(CORNER);
  image(trailLayer, 0, 0);

	//***  saveFrames('frame', 'png', 1, 1);
}

// ── Particle class ────────────────────────────────────────────
class Particle {
  constructor() {
    this.x         = -5;
    this.y         = random(height);
    this.vx        = random(2.5, 5.5);
    this.vy        = random(-0.9, 0.9);
    this.stuck     = false;
    this.size      = random(1.8, 4.5);
    this.shapeType = floor(random(2));
    this.age       = 0;
    this.hueBase   = random(PALETTE_HUES); // pick one of the defined palette colors
    this.stuckHue  = 0;           // set the moment it lands
  }

  update() {
    if (this.stuck) {
      this.age = min(255, this.age + 2);
      return;
    }

    let ax = 0.18;
    let n  = noise(this.x * 0.008, this.y * 0.008, frameCount * 0.005);
    let ay = map(n, 0, 1, -0.28, 0.28);

    this.vx = min(5.5, this.vx + ax);
    this.vy = max(-4, min(4, this.vy + ay));
    this.x += this.vx;
    this.y += this.vy;

    let cx = floor(this.x / CELL);
    let cy = floor(this.y / CELL);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        let cell = spatialGrid[(cx+dx) + ',' + (cy+dy)];
        if (!cell) continue;
        for (let t of cell) {
          if (t.claimed) continue;
          let ddx = this.x - t.x;
          let ddy = this.y - t.y;
          if (ddx*ddx + ddy*ddy < 100) {
            this.stuck = true;
            this.x = t.x;
            this.y = t.y;
            t.claimed = true;
            // Freeze the hue this particle was carrying at the moment it lands
            this.stuckHue = (this.hueBase + sin(frameCount * 0.02 + this.x * 0.01) * 8 + 360) % 360;
            return;
          }
        }
      }
    }
  }
}

